from itertools import product
from pqattest import *

def dedup(t):
    out=[]
    for x in t:
        if x not in out: out.append(x)
    return tuple(out)

def unit_vectors(k):
    return [tuple(1 if i==j else 0 for j in range(k)) for i in range(k)]

def candidate_weights(k):
    # unit vectors and small composites incl zeros, values 0..3 with <=2 nonzeros
    cands=set()
    for u in unit_vectors(k): cands.add(u)
    for i in range(k):
        for v in range(1,4):
            cands.add(tuple(v if j==i else 0 for j in range(k)))
    for i in range(k):
        for j in range(i+1,k):
            for a in (1,2,3):
                for b in (1,2,3):
                    cands.add(tuple(a if t==i else b if t==j else 0 for t in range(k)))
    return [c for c in cands if any(c)]

configs = {
 "deployment": dict(
    fn=recommend_merkle_deployment_weighted_scenarios,
    args=lambda sc:(16,(None,None,None,9000),sc), k=4),
 "transport_deployment": dict(
    fn=recommend_merkle_transport_deployment_weighted_scenarios,
    args=lambda sc:(4,(1,2),(None,None,None,9000),sc), k=5),
 "transport_workload": dict(
    fn=recommend_merkle_transport_workload_weighted_scenarios,
